def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_last, opp_last = history[-1]
    opp_prev = history[-2][1] if n >= 2 else 'C'

    # Count overall opponent cooperation
    opp_C = 0
    for _, o in history:
        if o == 'C':
            opp_C += 1
    opp_coop_rate = opp_C / n

    # If opponent is almost always defecting, defect
    if n >= 5 and opp_coop_rate < 0.2:
        return 'D'

    # If opponent has defected in the last 5 rounds, defect
    if n >= 5:
        all_D = True
        for i in range(n - 5, n):
            if history[i][1] != 'D':
                all_D = False
                break
        if all_D:
            return 'D'

    # Exploit: if we defected and opponent cooperated, keep defecting
    if my_last == 'D' and opp_last == 'C':
        return 'D'

    remaining = 100 - n
    # Endgame: defect on the last round
    if remaining <= 1:
        return 'D'

    # Probe: if we have seen 12 consecutive CC, defect to test
    if n >= 12:
        all_CC = True
        for i in range(n - 12, n):
            if history[i][0] != 'C' or history[i][1] != 'C':
                all_CC = False
                break
        if all_CC and remaining > 5:
            return 'D'

    # Handle opponent's last move
    if opp_last == 'D':
        if my_last == 'C':
            if opp_prev == 'D':
                return 'D'
            else:
                return 'C'
        else:
            return 'C'
    else:
        # opp_last == 'C'
        if my_last == 'C':
            return 'C'
        else:
            return 'D'
